fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, select the Lists application, and open the 'Categories' section. Click 'New Category' to open the create dialog. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Success is that the dialog shows a Name field, a Description field, and a 'Parent Category' dropdown (offering '(Top Level)' plus any existing categories), and that the 'Create' button is disabled while the Name is blank and enables once you type a name. You do NOT need to actually create the category — cancel after verifying the parent dropdown and the required-name gating.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The 'Create Category' dialog renders Name, Description, and a 'Parent Category' dropdown that includes a '(Top Level)' option",
    "The 'Create' button is disabled when Name is empty and becomes enabled after a name is typed",
    "No error messages, blank screens, or crash pages"
  ]
}
